using System;
using UnityEngine;
using GuildMaster.Database;
using GuildMaster.Infrastructure.DataProviders;
using GuildMaster.Infrastructure.Serialization;
using GuildMaster.Runtime.Core;
using GuildMaster.Runtime.Formulas;
using GuildMaster.Runtime.Services;
using GuildMaster.Runtime.Save;

namespace GuildMaster.Runtime.Boot
{
    public class Bootstrapper : MonoBehaviour
    {
        public bool RuntimeReady { get; private set; }

        // Composition Root Instances
        public ServiceContainer Services { get; private set; }
        public GameDatabase Database { get; private set; }
        public RuntimeFactory Factory { get; private set; }
        public IFormulaService FormulaService { get; private set; }
        public ISaveService SaveService { get; private set; }

        private void Start()
        {
            InitializePipeline();
        }

        private void InitializePipeline()
        {
            try
            {
                Debug.Log("[Bootstrapper] Starting Pipeline...");

                // 1. Provider
                IGameDataProvider dataProvider;
#if UNITY_EDITOR
                dataProvider = new EditorExternalGameDataProvider();
#else
                dataProvider = new StreamingAssetsGameDataProvider();
#endif

                // 2. Serializer
                var serializer = new UnityJsonSerializer();

                // 3. Database
                Database = new GameDatabase();

                // 4. Definition Registry (Build Database)
                var builder = new DatabaseBuilder(dataProvider, serializer, Database);
                var report = builder.Build();

                if (report.hasFatalErrors)
                {
                    throw new Exception("Database build encountered fatal errors.");
                }

                // 5. ServiceContainer (Composition Root)
                Services = new ServiceContainer(Database);
                FormulaService = Services.Formula;
                SaveService = Services.Save;
                Factory = Services.Factory;

                // 6. Runtime Ready
                RuntimeReady = true;
                Debug.Log("[Bootstrapper] Runtime Ready with ServiceContainer. Waiting for Scene transition...");
            }
            catch (Exception ex)
            {
                // If Fatal
                RuntimeReady = false;
                Debug.LogError($"[Bootstrapper] FATAL BOOT ERROR: {ex.Message}\n{ex.StackTrace}");
                // Giữ nguyên trạng thái Boot, không chuyển sang Main
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using GuildMaster.Definitions;

namespace GuildMaster.Database
{
    public class GameDatabase
    {
        private readonly Dictionary<Type, object> _registries = new Dictionary<Type, object>();

        // Register a full collection of typed definitions
        public void RegisterCollection<T>(IEnumerable<T> definitions) where T : DefinitionBase
        {
            var type = typeof(T);
            var dict = new Dictionary<string, T>(StringComparer.OrdinalIgnoreCase);

            foreach (var def in definitions)
            {
                if (string.IsNullOrEmpty(def.id))
                {
                    UnityEngine.Debug.LogWarning($"[GameDatabase] Skipping {type.Name} with null or empty ID.");
                    continue;
                }

                if (!dict.ContainsKey(def.id))
                {
                    dict[def.id] = def;
                }
                else
                {
                    UnityEngine.Debug.LogWarning($"[GameDatabase] Duplicate ID found in {type.Name}: {def.id}");
                }
            }

            _registries[type] = dict;
        }

        public void Add<T>(T def) where T : DefinitionBase
        {
            var type = typeof(T);
            if (!_registries.TryGetValue(type, out var registryObj))
            {
                registryObj = new Dictionary<string, T>(StringComparer.OrdinalIgnoreCase);
                _registries[type] = registryObj;
            }
            ((Dictionary<string, T>)registryObj)[def.id] = def;
        }

        public bool TryGet<T>(string id, out T definition) where T : DefinitionBase
        {
            definition = null;
            if (string.IsNullOrEmpty(id)) return false;

            if (_registries.TryGetValue(typeof(T), out var registryObj))
            {
                var dict = (Dictionary<string, T>)registryObj;
                return dict.TryGetValue(id, out definition);
            }
            return false;
        }

        public T GetRequired<T>(string id) where T : DefinitionBase
        {
            if (TryGet<T>(id, out var def))
            {
                return def;
            }
            throw new KeyNotFoundException($"Definition of type {typeof(T).Name} with ID '{id}' was not found in GameDatabase.");
        }

        public IReadOnlyCollection<T> GetAll<T>() where T : DefinitionBase
        {
            if (_registries.TryGetValue(typeof(T), out var registryObj))
            {
                var dict = (Dictionary<string, T>)registryObj;
                return dict.Values;
            }
            return Array.Empty<T>();
        }
    }
}

using UnityEngine;
using UnityEngine.SceneManagement;

namespace GuildMaster.Runtime.Boot
{
    /// <summary>
    /// Minimal Boot -> Main scene transition for real builds (Standalone/APK), where
    /// Boot.unity is the first scene in Build Settings. Editor Play Mode on Main.unity
    /// directly does not go through this. No composition/service wiring here — that
    /// stays in UIRuntimeBootstrap (S5) inside Main.unity.
    /// </summary>
    public class BootSceneLoader : MonoBehaviour
    {
        [SerializeField] private string _mainSceneName = "Main";

        private void Start()
        {
            SceneManager.LoadScene(_mainSceneName);
        }
    }
}

using System;
using UnityEngine;
using UnityEngine.UI;
using GuildMaster.Database;
using GuildMaster.Infrastructure.DataProviders;
using GuildMaster.Infrastructure.Serialization;
using GuildMaster.Runtime.Core;
using GuildMaster.Runtime.Formulas;
using GuildMaster.Runtime.Save;
using GuildMaster.Runtime.Services;
using GuildMaster.Runtime.UI;
using GuildMaster.Runtime.UI.Core;
using GuildMaster.Runtime.UI.HUD;
using GuildMaster.Runtime.UI.Inventory;
using GuildMaster.Runtime.UI.Character;
using GuildMaster.Runtime.UI.Popup;
using GuildMaster.Runtime.UI.Tavern;
