namespace GuildMaster.Runtime.Services
{
    public interface IOfflineProgressService
    {
        long CalculateOfflineDeltaSeconds(long lastSaveUnix, long currentUnix);
        OfflineProgressResult ApplyOfflineProgress(long currentUnix);
    }
}

using System;
using GuildMaster.Runtime.Models;
using GuildMaster.Runtime.Save;

namespace GuildMaster.Runtime.Services
{
    public class OfflineProgressService : IOfflineProgressService
    {
        private readonly ISaveService _saveService;
        private readonly ICraftService _craftService;
        private readonly IMerchantService _merchantService;

        private const long Cap12Hours = 12 * 3600;

        public OfflineProgressService(ISaveService saveService, ICraftService craftService, IMerchantService merchantService)
        {
            _saveService = saveService ?? throw new ArgumentNullException(nameof(saveService));
            _craftService = craftService ?? throw new ArgumentNullException(nameof(craftService));
            _merchantService = merchantService ?? throw new ArgumentNullException(nameof(merchantService));
        }

        public long CalculateOfflineDeltaSeconds(long lastSaveUnix, long currentUnix)
        {
            if (lastSaveUnix <= 0) return 0;
            if (currentUnix <= lastSaveUnix) return 0;

            long delta = currentUnix - lastSaveUnix;
            return Math.Min(delta, Cap12Hours);
        }

        public OfflineProgressResult ApplyOfflineProgress(long currentUnix)
        {
            var metadata = _saveService.CurrentData?.Metadata;
            if (metadata == null) 
            {
                return new OfflineProgressResult { Success = false, DeltaSeconds = 0, DispatchDeferred = false };
            }

            long delta = CalculateOfflineDeltaSeconds(metadata.SaveTimeUnix, currentUnix);

            // Save new last access time
            metadata.SaveTimeUnix = currentUnix;

            if (delta > 0)
            {
                // Dispatch to safe services (Craft and Merchant queues)
                _craftService.ProgressWorkshop(delta);
                _merchantService.ProgressMarket(delta);

                // Dungeon tick deferred: No safe background dungeon loop implemented yet.
                // Combat / Quest offline logic deferred.

                return new OfflineProgressResult 
                { 
                    Success = true, 
                    DeltaSeconds = delta, 
                    DispatchDeferred = true 
                };
            }

            return new OfflineProgressResult { Success = true, DeltaSeconds = 0, DispatchDeferred = false };
        }
    }
}

using System;
using GuildMaster.Database;
using GuildMaster.Runtime.Core;
using GuildMaster.Runtime.Formulas;
using GuildMaster.Runtime.Save;

namespace GuildMaster.Runtime.Services
{
    /// <summary>
    /// Central composition root container holding singletons for all runtime services.
    /// Guarantees that a single shared ISaveService, IFormulaService, and GameDatabase
    /// are injected across the entire game loop.
    /// </summary>
    public class ServiceContainer
    {
        public GameDatabase Database { get; }
        public RuntimeFactory Factory { get; }
        public IFormulaService Formula { get; }
        public ISaveService Save { get; }

        public IItemService Item { get; }
        public IInventoryService Inventory { get; }
        public ICharacterService Character { get; }
        public IEquipmentService Equipment { get; }
        public ISkillService Skill { get; }
        public IStatusEffectService StatusEffect { get; }
        public ICraftService Craft { get; }
        public IMerchantService Merchant { get; }
        public IDungeonService Dungeon { get; }
        public ICombatService Combat { get; }
        public ITargetSelectionService TargetSelection { get; }
        public ILootService Loot { get; }
        public IQuestService Quest { get; }
        public IDoctrineService Doctrine { get; }
        public IPromotionService Promotion { get; }
        public ITavernService Tavern { get; }
        public ISettingsService Settings { get; }
        public IOfflineProgressService OfflineProgress { get; }
        public IGameLoopService GameLoop { get; }
        public IPetService Pet { get; }

        public ServiceContainer(
            GameDatabase database, 
            ISaveService saveService = null, 
            IFormulaService formulaService = null,
            RuntimeFactory factory = null)
        {
            Database = database ?? throw new ArgumentNullException(nameof(database));
            Formula = formulaService ?? new FormulaService();

            if (saveService == null)
            {
                var newSave = new SaveService();
                newSave.Load(out _);
                Save = newSave;
            }
            else
            {
                Save = saveService;
            }

            Factory = factory ?? new RuntimeFactory(new DefaultInstanceIdGenerator());

            Item = new ItemService(Factory, Database);
            Inventory = new InventoryService(Save, Formula, Item, Database);
            Pet = new PetService(Save, Database);
            Character = new CharacterService(Save, Formula, Database, Factory, Inventory, Pet);
            Equipment = new EquipmentService(Inventory, Save);
            Skill = new SkillService();
            StatusEffect = new StatusEffectService();
            Craft = new CraftService(Database, Inventory, Save);
            Merchant = new MerchantService(Database, Inventory, Save);
            Combat = new CombatService(Character, Pet);
            TargetSelection = new TargetSelectionService();
            Loot = new LootService();

            Doctrine = new DoctrineService(Save, Formula);
            Promotion = new PromotionService(Save, Database, Inventory, Character);
            Quest = new QuestService(Save, Database, Doctrine);
            // Dungeon drives the run loop, so it needs combat, loot, characters, inventory and quest.
            Dungeon = new DungeonService(Save, Database, Combat, Loot, Character, Inventory, Quest);
            Tavern = new TavernService(Save, Formula, Character, Database);
            Settings = new SettingsService(Save);
            OfflineProgress = new OfflineProgressService(Save, Craft, Merchant);
            GameLoop = new GameLoopService(Save, Tavern, Merchant, Craft, Dungeon);
        }
    }
}

using System.Collections.Generic;
using UnityEngine;

namespace GuildMaster.Runtime.UI.Core
{
    public class UIService : IUIService
    {
        private readonly Dictionary<UIScreenId, UIScreen> _screens = new Dictionary<UIScreenId, UIScreen>();
        private readonly Stack<UIScreenId> _screenStack = new Stack<UIScreenId>();
        private UIScreenId _currentPopup = UIScreenId.None;

        public void RegisterScreen(UIScreen screen)
        {
            if (screen == null) return;
            _screens[screen.ScreenId] = screen;
            screen.Hide(); // default state
        }

        public void ShowScreen(UIScreenId screenId)
        {
            if (!_screens.ContainsKey(screenId))
            {
                Debug.LogWarning($"[UIService] Screen {screenId} not registered. (Deferred or Placeholder)");
                return;
            }

            // Hide current screen if any
            if (_screenStack.Count > 0)
            {
                var current = _screenStack.Peek();
                if (_screens.TryGetValue(current, out var currentScreen))
                {
                    currentScreen.Hide();
                }
            }

            _screenStack.Push(screenId);
            _screens[screenId].Show();
        }

        public void HideScreen(UIScreenId screenId)
        {
            if (_screens.TryGetValue(screenId, out var screen))
            {
                screen.Hide();
            }
        }

        public void Back()
        {
            if (_screenStack.Count <= 1) return; // Don't pop the root screen

            var current = _screenStack.Pop();
            HideScreen(current);

            var previous = _screenStack.Peek();
            if (_screens.TryGetValue(previous, out var prevScreen))
            {
                prevScreen.Show();
            }
        }

        public void ShowPopup(UIScreenId popupId)
        {
            if (!_screens.ContainsKey(popupId))
            {
                Debug.LogWarning($"[UIService] Popup {popupId} not registered.");
                return;
            }

            if (_currentPopup != UIScreenId.None)
            {
                ClosePopup();
            }

            _currentPopup = popupId;
            _screens[popupId].Show();
        }

        public void ClosePopup()
        {
            if (_currentPopup != UIScreenId.None && _screens.TryGetValue(_currentPopup, out var popup))
            {
                popup.Hide();
                _currentPopup = UIScreenId.None;
            }
        }

        // S4 Dialog System
        private GuildMaster.Runtime.UI.Popup.PopupScreen _dialogScreen;

        public void RegisterDialogScreen(GuildMaster.Runtime.UI.Popup.PopupScreen popupScreen)
        {
            _dialogScreen = popupScreen;
            if (_dialogScreen != null) _dialogScreen.Hide();
        }

        public void ShowInfo(string title, string message)
        {
            if (_dialogScreen != null)
            {
                _dialogScreen.ShowMessage(title, message);
            }
            else
            {
                Debug.LogWarning($"[UIService] ShowInfo: {title} - {message} (No Dialog Registered)");
            }
        }

        public void ShowError(string title, string message)
        {
            ShowInfo($"[Error] {title}", message);
        }

        public void ShowDeferred()
        {
            if (_dialogScreen != null)
            {
                _dialogScreen.ShowDeferred();
            }
            else
            {
                Debug.LogWarning("[UIService] Feature Deferred (No Dialog Registered)");
            }
        }
    }
}

